using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using UsedCarSales.Api.Data; using UsedCarSales.Api.DTOs; using UsedCarSales.Api.Models;
namespace UsedCarSales.Api.Controllers;
[ApiController, Route("api/[controller]")] public class SalesController(AppDbContext db) : ControllerBase { [HttpGet] public async Task<IActionResult> GetAll() => Ok(await db.Sales.Include(s=>s.Car).Include(s=>s.Customer).Include(s=>s.Billing).OrderByDescending(s=>s.SaleDate).ToListAsync()); [HttpPost] public async Task<IActionResult> Create(CreateSaleRequest r) { if(r.SalePrice<=0||r.Discount<0||r.Discount>r.SalePrice||r.TaxRate<0||r.TaxRate>1)return BadRequest("Check sale price, discount and tax rate."); await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable); var car=await db.Cars.FirstOrDefaultAsync(c=>c.Id==r.CarId); if(car is null)return NotFound("Car not found."); if(car.Status!="Available")return Conflict("This car is no longer available."); if(!await db.Customers.AnyAsync(c=>c.Id==r.CustomerId))return NotFound("Customer not found."); var subtotal=r.SalePrice-r.Discount; var tax=Math.Round(subtotal*r.TaxRate,2); var sale=new Sale { CarId=r.CarId, CustomerId=r.CustomerId, SalePrice=r.SalePrice, Discount=r.Discount, TaxRate=r.TaxRate, PaymentMethod=r.PaymentMethod, PaymentStatus=r.PaymentStatus, SaleDate=DateTime.UtcNow }; car.Status="Sold"; db.Sales.Add(sale); await db.SaveChangesAsync(); var bill=new Billing { SaleId=sale.Id, InvoiceNumber=$"INV-{DateTime.UtcNow:yyyyMMdd}-{sale.Id:0000}", Subtotal=r.SalePrice, Discount=r.Discount, TaxAmount=tax, TotalAmount=subtotal+tax }; db.Billings.Add(bill); await db.SaveChangesAsync(); await tx.CommitAsync(); return Ok(await db.Sales.Include(s=>s.Car).Include(s=>s.Customer).Include(s=>s.Billing).FirstAsync(s=>s.Id==sale.Id)); } }
